type WorkspaceKey = 'Overview' | 'Research' | 'Strategy Lab' | 'Trading' | 'Sample Portfolios' | 'Portfolio Risk' | 'Optimization Lab' | 'Research Studio' | 'Correlation' | 'Experiments' | 'Watchlist' | 'Data Quality' | AnalyticsTab
type NumericBar = { datetime: string; open: number; high: number; low: number; close: number; volume: number | null }
type SavedItem = { id: string; name: string; createdAt: string }
type BacktestItem = SavedItem & { symbol: string; metrics?: Record<string, unknown>; config?: BacktestConfig; equity?: { datetime: string; value: number; benchmark: number }[]; trades?: unknown[] }
type SavedStrategyItem = SavedItem & { config: BacktestConfig; description: string }
type UserWorkspace = { watchlist: { id: string; symbol: string; companyName: string }[]; portfolios: PortfolioOption[]; holdings: PortfolioHolding[]; strategies: SavedStrategyItem[]; backtests: BacktestItem[]; experiments: (SavedItem & { symbol: string; config?: BacktestConfig; results?: { fastWindow: number; slowWindow: number; totalReturn: number | null; sharpe: number | null; maxDrawdown: number | null; trades: number }[] })[] }
type MarketStatus = { configured: boolean; providers: ProviderConnection[] }
type MarketResponse = { data?: Instrument[]; warnings?: string[]; values?: MarketBar[]; source?: ProviderId; meta?: { exchange?: string; currency?: string } }
const marketHistoryUrl = (symbol: string, outputsize = 750) => `/api/market?action=history&symbol=${encodeURIComponent(symbol)}&interval=1day&outputsize=${outputsize}`
const portfolioBenchmarks = [{ symbol: 'AUTO', label: 'Auto by market' }, { symbol: 'SPY', label: 'S&P 500 (SPY)' }, ...INDIA_BENCHMARKS]
const fetcher = async <T,>(url: string): Promise<T> => {
  let response: Response
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(15_000) })
  } catch (error) {
    if (error instanceof Error && error.name === 'TimeoutError') throw new Error('The request timed out. Please try again.')
    if (error instanceof TypeError) throw new Error('The server could not be reached. Check your connection and try again.')
    throw error
  }
  const data = await response.json().catch(() => null)
  if (!response.ok) throw new Error(data && typeof data.error === 'string' ? data.error : `Request failed (${response.status}).`)
  if (data == null) throw new Error('The server returned an unreadable response. Please try again.')
  return data as T
}
